package dev.veltraph.client.observation.unexpected;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static dev.veltraph.client.observation.unexpected.UnexpectedBehaviorMonitor.*;
final class OwnedCycleLandingIntentTest {
    final Context context=new Context(new Activation("pumpkin_melon",7,true),1,1,1);
    private Finding packet(UnexpectedBehaviorMonitor monitor,Context ctx,double x,long now){monitor.signal(ctx,Kind.POSITION,Cause.SERVER_POSITION_PACKET,now,150);return monitor.observe(new Observation(ctx,Kind.POSITION,Value.position(40,0,0),Value.position(x,0,0),now));}
    @Test void successfulIssuedExactLandingExplainsOnlyOnePacket(){var monitor=new UnexpectedBehaviorMonitor(f->{});var issued=new AtomicBoolean();monitor.intent(context,Kind.POSITION,Value.position(0,0,0),.35,100,5000,issued::get);issued.set(true);var finding=packet(monitor,context,0,101);assertEquals(Classification.EXPLAINED,finding.classification());assertTrue(finding.evidence().contains(Cause.MOD_INTENT));assertEquals(Classification.UNEXPECTED,packet(monitor,context,0,102).classification());}
    @Test void failedOrUnissuedDispatchCannotExplainLanding(){var monitor=new UnexpectedBehaviorMonitor(f->{});monitor.intent(context,Kind.POSITION,Value.position(0,0,0),.35,100,5000,()->false);assertEquals(Classification.UNEXPECTED,packet(monitor,context,0,101).classification());}
    @Test void wrongLandingAndCancelledTicketRemainUnexpected(){var monitor=new UnexpectedBehaviorMonitor(f->{});long ticket=monitor.intent(context,Kind.POSITION,Value.position(0,0,0),.35,100,5000,()->true);assertEquals(Classification.UNEXPECTED,packet(monitor,context,10,101).classification());monitor.revokeIntent(ticket);assertEquals(Classification.UNEXPECTED,packet(monitor,context,0,102).classification());}
    @Test void oldCancelDoesNotRevokeNewerIntent(){var monitor=new UnexpectedBehaviorMonitor(f->{});long old=monitor.intent(context,Kind.POSITION,Value.position(0,0,0),.35,100,5000,()->true);monitor.intent(context,Kind.POSITION,Value.position(5,0,0),.35,101,5000,()->true);monitor.revokeIntent(old);assertEquals(Classification.EXPLAINED,packet(monitor,context,5,102).classification());}
    @Test void foreignNativeContextAndOwnerGenerationRevoke(){for(Context next:new Context[]{new Context(new Activation("pumpkin_melon",8,true),1,1,1),new Context(context.activation(),2,1,1),new Context(context.activation(),1,2,1),new Context(context.activation(),1,1,2)}){var monitor=new UnexpectedBehaviorMonitor(f->{});monitor.intent(context,Kind.POSITION,Value.position(0,0,0),.35,100,5000,()->true);monitor.context(next,101);assertEquals(Classification.UNEXPECTED,packet(monitor,next,0,102).classification());}}
    @Test void expiredOrFailedValidityCannotExplain(){for(boolean throwsFailure:new boolean[]{false,true}){var monitor=new UnexpectedBehaviorMonitor(f->{});monitor.intent(context,Kind.POSITION,Value.position(0,0,0),.35,100,10,()->{if(throwsFailure)throw new IllegalStateException("unavailable");return true;});assertEquals(Classification.UNEXPECTED,packet(monitor,context,0,throwsFailure?101:111).classification());}}
    @Test void cancelledGenerationCannotRegainTicketThroughAba(){var generation=new AtomicInteger(1);var monitor=new UnexpectedBehaviorMonitor(f->{});monitor.intent(context,Kind.POSITION,Value.position(0,0,0),.35,100,5000,()->generation.get()==1);generation.set(2);assertEquals(Classification.UNEXPECTED,packet(monitor,context,0,101).classification());generation.set(1);assertEquals(Classification.UNEXPECTED,packet(monitor,context,0,102).classification());}
    private void landingPacket(UnexpectedBehaviorMonitor monitor,double x,float yaw,long now){monitor.signal(context,Kind.POSITION,Cause.SERVER_POSITION_PACKET,now,150);monitor.signal(context,Kind.ROTATION,Cause.SERVER_POSITION_PACKET,now,150);monitor.ownedLandingPacket(context,Value.position(x,0,0),Value.rotation(yaw,-10),now);}
    private Finding view(UnexpectedBehaviorMonitor monitor,float yaw,long now){return monitor.observe(new Observation(context,Kind.ROTATION,Value.rotation(0,0),Value.rotation(yaw,-10),now));}
    @Test void sameOwnedNativePacketPositionAndViewAreOneUse(){var monitor=new UnexpectedBehaviorMonitor(f->{});monitor.ownedLandingIntent(context,Value.position(0,0,0),.35,100,5000,()->true);landingPacket(monitor,0,90,101);assertEquals(Classification.EXPLAINED,packet(monitor,context,0,101).classification());assertEquals(Classification.EXPLAINED,view(monitor,90,101).classification());assertEquals(Classification.UNEXPECTED,view(monitor,90,102).classification());}
    @Test void samePacketWrongLandingCannotExplainItsView(){var monitor=new UnexpectedBehaviorMonitor(f->{});monitor.ownedLandingIntent(context,Value.position(0,0,0),.35,100,5000,()->true);landingPacket(monitor,10,90,101);assertEquals(Classification.UNEXPECTED,packet(monitor,context,10,101).classification());assertEquals(Classification.UNEXPECTED,view(monitor,90,101).classification());}
    @Test void viewRequiresActualPositionAcknowledgmentAndCannotExplainDifferentRotation(){var monitor=new UnexpectedBehaviorMonitor(f->{});monitor.ownedLandingIntent(context,Value.position(0,0,0),.35,100,5000,()->true);landingPacket(monitor,0,90,101);assertEquals(Classification.UNEXPECTED,view(monitor,90,101).classification());assertEquals(Classification.EXPLAINED,packet(monitor,context,0,101).classification());assertEquals(Classification.UNEXPECTED,view(monitor,180,102).classification());}
    @Test void revokedReceiptCannotExplainPacketViewAfterPosition(){var owned=new AtomicBoolean(true);var monitor=new UnexpectedBehaviorMonitor(f->{});long ticket=monitor.ownedLandingIntent(context,Value.position(0,0,0),.35,100,5000,owned::get);landingPacket(monitor,0,90,101);assertEquals(Classification.EXPLAINED,packet(monitor,context,0,101).classification());owned.set(false);assertEquals(Classification.UNEXPECTED,view(monitor,90,102).classification());monitor.revokeIntent(ticket);}
    @Test void genericPositionIntentNeverExplainsAccompanyingServerView(){
        var monitor=new UnexpectedBehaviorMonitor(f->{});monitor.intent(context,Kind.POSITION,Value.position(0,0,0),.35,100,5000);landingPacket(monitor,0,90,101);
        assertEquals(Classification.EXPLAINED,packet(monitor,context,0,101).classification());assertEquals(Classification.UNEXPECTED,view(monitor,90,101).classification());
    }
    private UnexpectedBehaviorMonitor acknowledgedPair(java.util.function.BooleanSupplier valid){var monitor=new UnexpectedBehaviorMonitor(f->{});monitor.ownedLandingIntent(context,Value.position(0,0,0),.35,100,5000,valid);landingPacket(monitor,0,90,101);assertEquals(Classification.EXPLAINED,packet(monitor,context,0,101).classification());return monitor;}
    @Test void invalidPostAckScopeCannotResurrectThroughAba(){var valid=new AtomicBoolean(true);var monitor=acknowledgedPair(valid::get);valid.set(false);assertEquals(Classification.UNEXPECTED,view(monitor,90,102).classification());valid.set(true);assertEquals(Classification.UNEXPECTED,view(monitor,90,103).classification());}
    @Test void throwingPostAckScopeCannotResurrect(){var fail=new AtomicBoolean();var monitor=acknowledgedPair(()->{if(fail.get())throw new IllegalStateException("context unavailable");return true;});fail.set(true);assertEquals(Classification.UNEXPECTED,view(monitor,90,102).classification());fail.set(false);assertEquals(Classification.UNEXPECTED,view(monitor,90,103).classification());}
    @Test void clockRollbackClearsPostAckPairAndAcknowledgment(){var monitor=acknowledgedPair(()->true);monitor.context(context,99);monitor.signal(context,Kind.ROTATION,Cause.SERVER_POSITION_PACKET,100,150);assertEquals(Classification.UNEXPECTED,view(monitor,90,101).classification());}
    @Test void postAckNativeContextOrGenerationAbaCannotRestorePair(){for(Context different:new Context[]{new Context(new Activation("pumpkin_melon",8,true),1,1,1),new Context(context.activation(),2,1,1),new Context(context.activation(),1,2,1),new Context(context.activation(),1,1,2)}){var monitor=acknowledgedPair(()->true);monitor.context(different,102);monitor.context(context,103);monitor.signal(context,Kind.ROTATION,Cause.SERVER_POSITION_PACKET,103,150);assertEquals(Classification.UNEXPECTED,view(monitor,90,104).classification());}}
    @Test void newerIntentPermanentlySupersedesAcknowledgedPacketView(){var monitor=acknowledgedPair(()->true);monitor.intent(context,Kind.POSITION,Value.position(5,0,0),.35,102,5000);assertEquals(Classification.UNEXPECTED,view(monitor,90,103).classification());}
    @Test void newerServerPacketDiscardsOldPostAckView(){var monitor=acknowledgedPair(()->true);landingPacket(monitor,5,90,102);assertEquals(Classification.UNEXPECTED,view(monitor,90,103).classification());}
    @Test void oldReceiptCancelCannotRevokeNewerAcknowledgedPair(){var monitor=new UnexpectedBehaviorMonitor(f->{});long old=monitor.ownedLandingIntent(context,Value.position(0,0,0),.35,100,5000,()->true);monitor.ownedLandingIntent(context,Value.position(5,0,0),.35,101,5000,()->true);landingPacket(monitor,5,90,102);assertEquals(Classification.EXPLAINED,packet(monitor,context,5,102).classification());monitor.revokeIntent(old);assertEquals(Classification.EXPLAINED,view(monitor,90,103).classification());}
    @Test void genericRevocablePositionIntentAlsoRemainsPositionOnly(){var monitor=new UnexpectedBehaviorMonitor(f->{});monitor.intent(context,Kind.POSITION,Value.position(0,0,0),.35,100,5000,()->true);landingPacket(monitor,0,90,101);assertEquals(Classification.EXPLAINED,packet(monitor,context,0,101).classification());assertEquals(Classification.UNEXPECTED,view(monitor,90,101).classification());}
    @Test void scopeInvalidAtPacketCannotRegainOwnedPairBeforeObservation(){var valid=new AtomicBoolean(false);var monitor=new UnexpectedBehaviorMonitor(f->{});monitor.ownedLandingIntent(context,Value.position(0,0,0),.35,100,5000,valid::get);landingPacket(monitor,0,90,101);valid.set(true);assertEquals(Classification.UNEXPECTED,packet(monitor,context,0,102).classification());assertEquals(Classification.UNEXPECTED,view(monitor,90,102).classification());}
    @Test void mismatchedPostAckViewCannotLaterMatchOldPair(){var monitor=acknowledgedPair(()->true);assertEquals(Classification.UNEXPECTED,view(monitor,180,102).classification());assertEquals(Classification.UNEXPECTED,view(monitor,90,103).classification());}
    @Test void postAckConfigOrPlanAbaSeenByContextSamplingPermanentlyRevokes(){for(String field:new String[]{"config","plan","registration"}){var original=new Object();var value=new AtomicReference<Object>(original);var monitor=acknowledgedPair(()->value.get()==original);value.set(new Object());monitor.context(context,102);value.set(original);assertEquals(Classification.UNEXPECTED,view(monitor,90,103).classification(),field);}}
}
